import { test, expect } from '@playwright/test';

test.describe('Mark Record as Favourite', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should mark a record as favourite and display a star icon', async ({ page }) => {
    // Verify the records list is visible
    const recordsList = page.getByRole('region', { name: /records/i });
    await expect(recordsList).toBeVisible();

    // Locate and click the first record using getByRole
    const recordItem = page.getByRole('listitem', { name: /record 1/i });
    await expect(recordItem).toBeVisible();
    await recordItem.click();

    // Verify the record details modal is open
    const recordDetailsModal = page.locator('[data-testid="record-details-modal"]');
    await expect(recordDetailsModal).toBeVisible();

    // Verify the star icon is visible and not disabled
    const starIcon = page.getByRole('button', { name: /star/i });
    await expect(starIcon).toBeVisible();
    await expect(starIcon).not.toBeDisabled();

    // Click the star icon to mark as favourite
    await starIcon.click();

    // Verify the star icon is now active
    await expect(starIcon).toHaveAttribute('aria-pressed', 'true');

    // Verify the record is now marked as favourite
    const favouriteCount = page.getByText(/favourites/i);
    await expect(favouriteCount).toContainText('1');

    // Verify the star icon is displayed
    await expect(starIcon).toBeVisible();

    // Verify the record details modal is still open
    await expect(recordDetailsModal).toBeVisible();

    // Verify the record details are visible
    const recordName = page.getByText(/record 1/i);
    await expect(recordName).toBeVisible();

    // Verify the record details are updated with favourite status
    const favouriteStatus = page.getByText(/favourite/i);
    await expect(favouriteStatus).toBeVisible();

    // Verify the save button is enabled
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).not.toBeDisabled();

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify the records list is still visible
    await expect(recordsList).toBeVisible();
  });

  test('should not mark a record as favourite if already marked', async ({ page }) => {
    // Verify the records list is visible
    const recordsList = page.getByRole('region', { name: /records/i });
    await expect(recordsList).toBeVisible();

    // Locate and click the first record using getByRole
    const recordItem = page.getByRole('listitem', { name: /record 1/i });
    await expect(recordItem).toBeVisible();
    await recordItem.click();

    // Verify the record details modal is open
    const recordDetailsModal = page.locator('[data-testid="record-details-modal"]');
    await expect(recordDetailsModal).toBeVisible();

    // Verify the star icon is visible and not disabled
    const starIcon = page.getByRole('button', { name: /star/i });
    await expect(starIcon).toBeVisible();
    await expect(starIcon).not.toBeDisabled();

    // Click the star icon to mark as favourite
    await starIcon.click();

    // Verify the star icon is now active
    await expect(starIcon).toHaveAttribute('aria-pressed', 'true');

    // Verify the record is now marked as favourite
    const favouriteCount = page.getByText(/favourites/i);
    await expect(favouriteCount).toContainText('1');

    // Verify the record details are updated with favourite status
    const favouriteStatus = page.getByText(/favourite/i);
    await expect(favouriteStatus).toBeVisible();

    // Verify the save button is enabled
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).not.toBeDisabled();

    // Click the save button
    await saveButton.click();

    // Verify the record details modal closes
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify the records list is still visible
    await expect(recordsList).toBeVisible();

    // Verify the star icon is still visible and active
    await expect(starIcon).toBeVisible();
    await expect(starIcon).toHaveAttribute('aria-pressed', 'true');

    // Verify the record is still marked as favourite
    await expect(favouriteCount).toContainText('1');
  });
});
